{{-- Como ficam as mensalidades do cliente, contando a entrada como a 1ª. O app.js redesenha enquanto se digita. --}}
@php $free=(int)($campaign?->free_months ?? 1); $pct=(int)($campaign?->discount_percent ?? 0); $off=$pct>0 ? (int)($campaign?->discount_months ?? 0) : 0; @endphp
<ol class="campaign-flow" @if($live ?? true) data-campaign-flow @endif aria-label="Como ficam as mensalidades"><li><b>1ª</b>Entrada cheia</li>@for($n=2;$n<2+$free;$n++)<li class="is-free"><b>{{ $n }}ª</b>Grátis</li>@endfor @for($n=2+$free;$n<2+$free+$off;$n++)<li class="is-discount"><b>{{ $n }}ª</b>{{ $pct }}% de desconto</li>@endfor<li><b>{{ 2+$free+$off }}ª em diante</b>Preço normal</li></ol>
